head.script:
scwin.trigger10_onclick = function(e) {
    windowContainer1.createWindow("메시지관리", null, "windowContainer_existWindow_WEFF-861_(WSQ-4232)_sub1.xml", "메시지관리", "test1", "existWindow", scwin.closeAction);
};
scwin.trigger11_onclick = function(e) {
    windowContainer1.createWindow("메시지관리등록", null, "windowContainer_existWindow_WEFF-861_(WSQ-4232)_sub1.xml", "메시지관리등록", "test1", "existWindow", scwin.closeAction2);
};
scwin.closeAction = function(title, a) {
    console.log("title: " + title);
    textbox1.setValue("title: " + title);
    return true;
};
scwin.closeAction2 = function(title) {
    console.log("title2: " + title);
    textbox1.setValue("title2: " + title);
    return true;
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger10').click()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger11').click()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('windowContainer1_subWindow0_close').click()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#textbox1').text() == 'title2: 메시지관리등록'", "true");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
